// src/pages/Home.js
import React, { useEffect } from "react";
import Navigation from "../components/Navigation";
import Hero from "../components/Hero";
import Footer from "../components/Footer";
import AOS from "aos";
import "aos/dist/aos.css";

const Home = () => {
  useEffect(() => {
    AOS.init({ duration: 1000 });
  }, []);

  return (
    <>
      <Navigation />
      <Hero />

      {/* Features Section directly in Home.js */}
      <section className="features text-center my-5" id="features">
        <h2 data-aos="fade-up" className="fw-bold">Why Choose FI Money?</h2>
        <div className="container d-flex justify-content-center flex-wrap gap-4 mt-4">
          <div className="card p-4 shadow" data-aos="fade-right">
            <h3 className="fw-bold">No Hidden Fees</h3>
            <p>Enjoy zero maintenance charges and free transactions.</p>
          </div>
          <div className="card p-4 shadow" data-aos="fade-up">
            <h3 className="fw-bold">Smart Budgeting</h3>
            <p>Track expenses and set budgets with ease.</p>
          </div>
          <div className="card p-4 shadow" data-aos="fade-left">
            <h3 className="fw-bold">Secure & Fast</h3>
            <p>End-to-end encryption ensures your data is safe.</p>
          </div>
        </div>
      </section>

      <Footer />
    </>
  );
};

export default Home;
